/* ---------- Contato ---------- */

function Contato({ m }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(EMAIL);
    } catch (e) {
      const ta = document.createElement("textarea");
      ta.value = EMAIL;
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
      } catch (err) {}
      document.body.removeChild(ta);
    }
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <section id="contato" style={{ padding: m ? "0 20px 96px" : "0 96px 140px" }}>
      <div className={m ? "flex flex-col" : "grid items-center"} style={{ gridTemplateColumns: m ? undefined : "420px 1fr", gap: m ? 32 : 88 }}>
        <Reveal>
          <img
            src={FOTO}
            alt="João Baran de camisa branca, com os braços cruzados"
            className="rounded-3xl"
            style={{ display: "block", width: "100%", aspectRatio: "4 / 5", objectFit: "cover", maxHeight: m ? 440 : "none" }}
          />
        </Reveal>

        <Reveal delay={m ? 0 : 120}>
          <h2 style={h2(m)}>Vamos conversar.</h2>
          <p style={{ ...body(m), color: C.text2, marginTop: 14, maxWidth: 460 }}>
            Quer falar sobre engenharia, produto ou uma oportunidade? Me manda um e-mail.
          </p>

          <div className="flex items-center" style={{ marginTop: m ? 28 : 36, gap: 6 }}>
            <a href={`mailto:${EMAIL}`} className="jb-mail" style={{ fontSize: m ? 20 : 24, fontWeight: 600, textDecoration: "none" }}>
              {EMAIL}
            </a>
            <div style={{ position: "relative" }}>
              <button
                onClick={copy}
                aria-label={copied ? "E-mail copiado" : "Copiar e-mail"}
                className="jb-icon flex items-center justify-center rounded-full"
                style={{ width: 40, height: 40, color: copied ? C.accent : C.text3 }}
              >
                {copied ? <IconCheck /> : <IconCopy />}
              </button>
              <span
                role="status"
                style={{
                  position: "absolute",
                  left: "50%",
                  top: -30,
                  transform: `translateX(-50%) translateY(${copied ? 0 : 4}px)`,
                  opacity: copied ? 1 : 0,
                  transition: `opacity 200ms ease, transform 200ms ${EASE}`,
                  background: C.surface,
                  color: C.text,
                  fontSize: 12,
                  padding: "4px 8px",
                  borderRadius: 8,
                  whiteSpace: "nowrap",
                  pointerEvents: "none",
                }}
              >
                {copied ? "Copiado" : ""}
              </span>
            </div>
          </div>

          <a href="#" onClick={(e) => e.preventDefault()} className="jb-link inline-flex items-center" style={{ marginTop: 16, fontSize: 17, gap: 8, textDecoration: "none" }}>
            Ou fale comigo no LinkedIn
            <IconArrow />
          </a>
        </Reveal>
      </div>
    </section>
  );
}

