/* ---------- Moldura ---------- */

function Device({ device, scrollRef, children }) {
  const outer = useRef(null);
  const [scale, setScale] = useState(1);
  const { w, h } = DEVICES[device];
  useLayoutEffect(() => {
    const update = () => outer.current && setScale(Math.min(1, outer.current.clientWidth / w));
    update();
    const ro = new ResizeObserver(update);
    ro.observe(outer.current);
    return () => ro.disconnect();
  }, [w]);
  return (
    <div ref={outer} className="w-full">
      <div style={{ width: w * scale, height: h * scale, margin: "0 auto", borderRadius: device === "celular" ? 36 : 14, overflow: "hidden", border: "1px solid #2c2c2e" }}>
        <div ref={scrollRef} className="jb-scroll" style={{ position: "relative", width: w, height: h, transform: `scale(${scale})`, transformOrigin: "top left", overflowY: "auto", background: C.bg }}>
          {children}
        </div>
      </div>
    </div>
  );
}

function Toggle({ options, value, onChange }) {
  return (
    <div className="flex rounded-full" style={{ background: C.surface, padding: 3 }}>
      {options.map(([k, label]) => (
        <button key={k} onClick={() => onChange(k)} className="rounded-full" style={{ fontSize: 13, padding: "6px 12px", background: value === k ? "#3a3a3c" : "transparent", color: value === k ? C.text : C.text3 }}>
          {label}
        </button>
      ))}
    </div>
  );
}

export default function SiteCompleto() {
  const [device, setDevice] = useState("celular");
  const [page, setPage] = useState("home");
  const [runKey, setRunKey] = useState(0);
  const [pendingAnchor, setPendingAnchor] = useState(null);
  const scrollRef = useRef(null);
  const reduced = useReducedMotion();
  const m = device === "celular";

  const scrollTo = (id) => {
    const box = scrollRef.current;
    if (!box) return;
    const el = box.querySelector(`#${id}`);
    if (!el) return;
    let top = 0;
    let n = el;
    while (n && n !== box) {
      top += n.offsetTop;
      n = n.offsetParent;
    }
    box.scrollTo({ top: top - 8, behavior: reduced ? "auto" : "smooth" });
  };

  const go = (p) => {
    setPage(p);
    if (scrollRef.current) scrollRef.current.scrollTo({ top: 0 });
  };

  const home = (anchor) => {
    if (page !== "home") {
      setPage("home");
      setPendingAnchor(anchor || "__top");
    } else if (anchor) {
      scrollTo(anchor);
    } else if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: 0, behavior: reduced ? "auto" : "smooth" });
    }
  };

  useEffect(() => {
    if (page === "home" && pendingAnchor) {
      const a = pendingAnchor;
      setPendingAnchor(null);
      requestAnimationFrame(() => {
        if (a === "__top") scrollRef.current && scrollRef.current.scrollTo({ top: 0 });
        else scrollTo(a);
      });
    }
  }, [page, pendingAnchor]);

  const pages = {
    home: <Home m={m} runKey={runKey} reduced={reduced} />,
    lista: <Lista m={m} />,
    texto: <TextoPage m={m} />,
    cv: <CvAviso m={m} />,
    "404": <NaoEncontrada m={m} />,
  };

  return (
    <NavCtx.Provider value={{ go, scrollTo, home }}>
      <div className="min-h-screen" style={{ background: "#111113", color: C.text, fontFamily: "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif", padding: 16 }}>
        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap');
          svg { width: 100%; height: auto; display: block; font-family: Inter, -apple-system, BlinkMacSystemFont, sans-serif; }
          .jb-card svg, .jb-row svg, .jb-icon svg, .jb-link svg { width: auto; display: inline-block; }
          @keyframes jbBlink { 0%, 49% { opacity: 1 } 50%, 100% { opacity: 0 } }
          .jb-blink { animation: jbBlink 1.05s steps(1) infinite; }
          .jb-navlink { color: ${C.text2}; transition: color 200ms ease; }
          .jb-navlink:hover { color: ${C.text}; }
          .jb-btn { transition: background-color 200ms ease, transform 200ms ease; }
          .jb-btn:hover { background-color: #0077ED !important; }
          .jb-btn:active { transform: scale(0.98); }
          .jb-btn2 { color: ${C.text}; border: 1px solid ${C.text3}; transition: border-color 200ms ease, transform 200ms ease; }
          .jb-btn2:hover { border-color: ${C.text}; }
          .jb-btn2:active { transform: scale(0.98); }
          .jb-card { transition: transform 200ms ease; }
          .jb-card:hover { transform: translateY(-2px); }
          .jb-row .jb-arrow { transition: color 200ms ease, transform 200ms ease; }
          .jb-row:hover .jb-arrow { color: ${C.text}; transform: translate(2px, -2px); }
          .jb-item-t { color: ${C.text}; transition: color 200ms ease; }
          .jb-item:hover .jb-item-t { color: ${C.accent}; }
          .jb-mail { color: ${C.text}; transition: color 200ms ease; }
          .jb-mail:hover { color: ${C.accent}; }
          .jb-icon { transition: background-color 200ms ease, color 200ms ease; }
          .jb-icon:hover { background-color: ${C.surface}; }
          .jb-link { color: ${C.accent}; }
          .jb-link:hover { text-decoration: underline; }
          .jb-foot { color: ${C.text3}; transition: color 200ms ease; }
          .jb-foot:hover { color: ${C.text}; }
          a:focus-visible, button:focus-visible { outline: 2px solid ${C.accent}; outline-offset: 3px; }
          .jb-scroll::-webkit-scrollbar { display: none; }
          @media (prefers-reduced-motion: reduce) { .jb-blink { animation: none; } .jb-card:hover { transform: none; } }
        `}</style>

        <div style={{ maxWidth: 1320, margin: "0 auto" }}>
          <div style={{ marginBottom: 14 }}>
            <div className="font-semibold" style={{ fontSize: 17 }}>joaobaran.com: protótipo completo</div>
            <div style={{ fontSize: 13, color: C.text3, marginTop: 2 }}>Navegue dentro da tela como no site real: menu, botões e cards levam às páginas e seções.</div>
          </div>
          <div className="flex flex-wrap items-center" style={{ gap: 10, marginBottom: 16 }}>
            <Toggle options={[["celular", "Celular"], ["desktop", "Desktop"]]} value={device} onChange={setDevice} />
            <Toggle options={[["home", "Home"], ["lista", "/textos"], ["texto", "Texto"], ["404", "404"]]} value={page === "cv" ? "" : page} onChange={(p) => (p === "home" ? home() : go(p))} />
            <button onClick={() => { setPage("home"); setRunKey((k) => k + 1); scrollRef.current && scrollRef.current.scrollTo({ top: 0 }); }} className="rounded-full font-semibold" style={{ fontSize: 13, padding: "8px 14px", background: C.surface, color: C.text }}>
              Reproduzir abertura
            </button>
          </div>
          <Device device={device} scrollRef={scrollRef}>
            <div key={`${device}-${page}`}>
              <Menu m={m} />
              {pages[page]}
              <Rodape m={m} />
            </div>
          </Device>
        </div>
      </div>
    </NavCtx.Provider>
  );
}
